boolean insert(int val){
    // Initialize set
    Map<Integer, Integer> set = new HashMap<>();

    // Iterate through existing elements in the set
    for (Map.Entry<Integer, Integer> entry : set.entrySet()) {
        if (entry.getKey() == val) {
            // If the value already exists in the set, return false
            return false;
