private TreeNode<T> rotateRight(TreeNode<T> node){
    if(node == null || node.left == null) {
        return node; // No left child, return current node as is
    }

    TreeNode<T> newParent = node.left;
    TreeNode<T> newRightChild = newParent.right;

    // Relocate the current node as a child to the right of the new parent
    newParent.right = node;
    node.parent = newParent;

    // The left child of the original node is now the new right child
    newParent.left = newRightChild;

    // Optionally adjust the parent's left pointer if the right child became the new root
    if(newRightChild != null) {
        newRightChild.parent = node;
    }

    // Return the new parent node after the rotation
    return newParent;
}

