private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSumList = new ArrayList<>();
    long sum = 0;

    // If bounds list is empty, return empty suffix sum list and sum 0
    if (bounds.isEmpty()) {
        return new Pair<>(suffixSumList, 0L);
    }

    // Compute suffix sum list
    long currentSum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        currentSum += bounds.get(i);
        suffixSumList.add((int) currentSum);
    }

    // Compute the sum of all elements in the bounds list
    for (int num : bounds) {
        sum += num;
    }

    return new Pair<>(suffixSumList, sum);
}

