    } else {
        // Read the next byte to determine the number of bytes to decode
        int nextByte = bb.get(i);
        need = getNextByteCount(nextByte);
        if (need == 0) {
            throw new IllegalArgumentException("Invalid octet: " + nextByte);
        }
    }

    startNew(sb, need); // Initialize a new string buffer with the required capacity

    // Read the next 'need' bytes from the buffer
    for (int j = 0; j < need; j++) {
        byte nextByte = bb.get(i + j);
        // Only use non-null bytes in the new string buffer
        if (nextByte != 0) {
            sb.append((char) nextByte);
        }
    }

    // Return the index to the next unchecked character in the string to decode
    return i + need;
}

