        return 2;
    }
    int prime = -1;
    for (int i = 2; i < desiredCapacity * 1.111; i++) {
        if (isPrime(i)) {
            prime = i;
            break;
        }
    }
    if (prime == -1) {
        prime = (int) Math.sqrt(desiredCapacity) * 2; // Adjust to the nearest even number
        while (!isPrime(prime)) {
            prime += 2;
        }
    }
    return prime;
}

private static boolean isPrime(int number) {
    if (number <= 1) return false;
    if (number == 2) return true;
    if (number % 2 == 0) return false;
    for (int i = 3; i <= Math.sqrt(number); i += 2) {
        if (number % i == 0) return false;
    }
    return true;
}

